22	
23	import java.io.IOException;
24	import java.io.OutputStream;
25	
26	/**
27	 * {@link FSDataOutputStream} that delegates all writing operations to a wrapping {@link
28	 * StreamCompressionDecorator}.
29	 */
30	public class CompressibleFSDataOutputStream extends FSDataOutputStream {
31	
32	    private final FSDataOutputStream delegate;
33	    private final OutputStream compressingDelegate;
34	
35	    public CompressibleFSDataOutputStream(
36	            CheckpointStateOutputStream delegate, StreamCompressionDecorator compressionDecorator)
37	            throws IOException {
38	        this.delegate = delegate;
39	        this.compressingDelegate = compressionDecorator.decorateWithCompression(delegate);
40	    }
41	
42	    @Override
43	    public long getPos() throws IOException {
44	        return delegate.getPos();
45	    }
46	
47	    @Override
48	    public void write(int b) throws IOException {
49	        compressingDelegate.write(b);
50	    }
51	
52	    @Override
53	    public void flush() throws IOException {
54	        compressingDelegate.flush();
55	    }
56	
57	    @Override
58	    public void sync() throws IOException {
59	        delegate.sync();
60	    }
61	
62	    @Override
63	    public void close() throws IOException {
64	        compressingDelegate.close();
65	    }
66	}
