70	                CollectionUtil.newHashMapWithExpectedSize(registeredOperatorStates.size());
71	        final Map<String, BackendWritableBroadcastState<?, ?>> registeredBroadcastStatesDeepCopies =
72	                CollectionUtil.newHashMapWithExpectedSize(registeredBroadcastStates.size());
73	
74	        ClassLoader snapshotClassLoader = Thread.currentThread().getContextClassLoader();
75	        Thread.currentThread().setContextClassLoader(userClassLoader);
76	        try {
77	            // eagerly create deep copies of the list and the broadcast states (if any)
78	            // in the synchronous phase, so that we can use them in the async writing.
79	
80	            if (!registeredOperatorStates.isEmpty()) {
