19	package org.apache.flink.runtime.state;
20	
21	import org.apache.flink.annotation.VisibleForTesting;
22	import org.apache.flink.api.common.state.ListState;
23	import org.apache.flink.core.fs.FSDataOutputStream;
24	import org.apache.flink.core.memory.DataOutputView;
25	import org.apache.flink.core.memory.DataOutputViewStreamWrapper;
26	import org.apache.flink.util.Preconditions;
27	
28	import java.io.IOException;
29	import java.util.ArrayList;
30	import java.util.List;
31	
32	/**
33	 * Implementation of operator list state.
34	 *
35	 * @param <S> the type of an operator state partition.
36	 */
37	public final class PartitionableListState<S> implements ListState<S> {
38	
39	    /** Meta information of the state, including state name, assignment mode, and typeSerializer */
40	    private RegisteredOperatorStateBackendMetaInfo<S> stateMetaInfo;
41	
42	    /** The internal list the holds the elements of the state */
43	    private final ArrayList<S> internalList;
44	
45	    /** A typeSerializer that allows to perform deep copies of internalList */
46	    private ArrayListSerializer<S> internalListCopySerializer;
47	
48	    PartitionableListState(RegisteredOperatorStateBackendMetaInfo<S> stateMetaInfo) {
49	        this(stateMetaInfo, new ArrayList<S>());
50	    }
51	
52	    private PartitionableListState(
53	            RegisteredOperatorStateBackendMetaInfo<S> stateMetaInfo, ArrayList<S> internalList) {
54	
55	        this.stateMetaInfo = Preconditions.checkNotNull(stateMetaInfo);
56	        this.internalList = Preconditions.checkNotNull(internalList);
57	        this.internalListCopySerializer =
58	                new ArrayListSerializer<>(stateMetaInfo.getPartitionStateSerializer());
59	    }
60	
61	    private PartitionableListState(PartitionableListState<S> toCopy) {
62	
63	        this(
64	                toCopy.stateMetaInfo.deepCopy(),
65	                toCopy.internalListCopySerializer.copy(toCopy.internalList));
66	    }
67	
68	    public void setStateMetaInfo(RegisteredOperatorStateBackendMetaInfo<S> stateMetaInfo) {
69	        this.internalListCopySerializer =
70	                new ArrayListSerializer<>(stateMetaInfo.getPartitionStateSerializer());
71	        this.stateMetaInfo = stateMetaInfo;
72	    }
73	
74	    public RegisteredOperatorStateBackendMetaInfo<S> getStateMetaInfo() {
75	        return stateMetaInfo;
76	    }
77	
78	    public PartitionableListState<S> deepCopy() {
79	        return new PartitionableListState<>(this);
80	    }
81	
82	    @Override
83	    public void clear() {
84	        internalList.clear();
85	    }
86	
87	    @Override
88	    public Iterable<S> get() {
89	        return internalList;
90	    }
91	
92	    @Override
93	    public void add(S value) {
94	        Preconditions.checkNotNull(value, "You cannot add null to a ListState.");
95	        internalList.add(value);
96	    }
97	
98	    @Override
99	    public String toString() {
100	        return "PartitionableListState{"
101	                + "stateMetaInfo="
102	                + stateMetaInfo
103	                + ", internalList="
104	                + internalList
105	                + '}';
106	    }
107	
108	    public long[] write(FSDataOutputStream out) throws IOException {
109	
110	        long[] partitionOffsets = new long[internalList.size()];
111	
112	        DataOutputView dov = new DataOutputViewStreamWrapper(out);
113	
114	        for (int i = 0; i < internalList.size(); ++i) {
115	            S element = internalList.get(i);
116	            partitionOffsets[i] = out.getPos();
117	            getStateMetaInfo().getPartitionStateSerializer().serialize(element, dov);
118	        }
