+import org.xerial.snappy.SnappyFramedInputStream;
+import org.xerial.snappy.SnappyFramedOutputStream;
+import java.io.*;
+import java.nio.charset.StandardCharsets;
+import java.util.*;
+
+public class SnappyProbe {
+    public static void main(String[] a) throws Exception {
+        List<String> words = Arrays.asList("first","second","third","fourth","fifth");
+        ByteArrayOutputStream raw = new ByteArrayOutputStream();
+        // Filter to record positions; but we need position in raw. We'll flush before each.
+        SnappyFramedOutputStream sout = new SnappyFramedOutputStream(raw, 64*1024, 0.85d);
+        Map<String,Integer> off = new HashMap<>();
+        for (String w: words){
+            sout.flush();
+            off.put(w, raw.size());
+            sout.write(w.getBytes(StandardCharsets.UTF_8));
+        }
+        sout.flush();
+        byte[] bytes = raw.toByteArray();
+        sout.close();
+        System.out.println("offsets="+off+" total="+bytes.length);
+
+        // Try: single SnappyFramedInputStream over a seekable byte stream, seek by recreating.
+        for (String w: Arrays.asList("first","third","fifth")){
+            ByteArrayInputStream bin = new ByteArrayInputStream(bytes, off.get(w), bytes.length-off.get(w));
+            SnappyFramedInputStream sin = new SnappyFramedInputStream(bin, false);
+            byte[] buf = new byte[w.length()];
+            int n=0; while(n<buf.length){int r=sin.read(buf,n,buf.length-n); if(r<0)break; n+=r;}
+            System.out.println("recreate read "+w+" -> '"+new String(buf,StandardCharsets.UTF_8)+"'");
+        }
+    }
+}
