+import org.xerial.snappy.SnappyFramedInputStream;
+import org.xerial.snappy.SnappyFramedOutputStream;
+import java.io.*;
+import java.nio.charset.StandardCharsets;
+import java.util.*;
+
+public class SnappyProbe2 {
+    // Seekable in-memory stream
+    static class SeekableIn extends InputStream {
+        byte[] data; int pos;
+        SeekableIn(byte[] d){data=d;}
+        public void seek(int p){pos=p;}
+        public int read(){ return pos<data.length ? (data[pos++]&0xff) : -1; }
+        public int read(byte[]b,int o,int l){ if(pos>=data.length)return -1; int n=Math.min(l,data.length-pos); System.arraycopy(data,pos,b,o,n); pos+=n; return n; }
+    }
+    static String readN(InputStream s,int n) throws IOException{ byte[]b=new byte[n]; int r=0; while(r<n){int x=s.read(b,r,n-r); if(x<0)break; r+=x;} return new String(b,0,r,StandardCharsets.UTF_8);}
+    public static void main(String[] a) throws Exception {
+        List<String> words = Arrays.asList("first","second","third","fourth","fifth");
+        ByteArrayOutputStream raw = new ByteArrayOutputStream();
+        SnappyFramedOutputStream sout = new SnappyFramedOutputStream(raw, 64*1024, 0.85d);
+        Map<String,Integer> off = new HashMap<>();
+        for (String w: words){ sout.flush(); off.put(w, raw.size()); sout.write(w.getBytes(StandardCharsets.UTF_8)); }
+        sout.flush(); byte[] bytes = raw.toByteArray(); sout.close();
+        System.out.println("offsets="+off);
+
+        SeekableIn sk = new SeekableIn(bytes);
+        SnappyFramedInputStream sin = new SnappyFramedInputStream(sk, false);
+        // read first fully
+        sk.seek(off.get("first"));
+        System.out.println("first(after seek to 10)='"+readN(sin,5)+"'");
+        // now seek to third and read WITHOUT discarding
+        sk.seek(off.get("third"));
+        System.out.println("third(no discard)='"+readN(sin,5)+"'");
+    }
+}
